/// <summary>
/// Stages csd transfer order types value.
/// </summary>
/// <returns>
/// METFulfilmentRuleValueLookupTmp record.
/// </returns>
public static METFulfilmentRuleValueLookupTmp stageCSDTOType()
{
    METFulfilmentRuleValueLookupTmp lookupTmp;
    DictEnum  dictEnum;

    dictEnum = new DictEnum(enumNum(METCSDTOType));

    if (dictEnum.id())
    {
        for (int counter = 0; counter < dictEnum.values(); counter++)
        {
            ttsbegin;

            lookupTmp.clear();

            lookupTmp.Value = dictEnum.index2Name(counter);
            lookupTmp.insert();
            ttscommit;
        }
    }

    return lookupTmp;
}

/// <summary>
/// Stages csd transfer order types value.
/// </summary>
/// <returns>
/// METFulfilmentRuleValueLookupTmp record.
/// </returns>
public static METFulfilmentRuleValueLookupTmp stageOrderType()
{
    METFulfilmentRuleValueLookupTmp lookupTmp;

    ttsbegin;

    lookupTmp.Value = METConstants::GRONOrderType;
    lookupTmp.insert();

    lookupTmp.clear();

    lookupTmp.Value = METConstants::PERNOrderType;
    lookupTmp.insert();

    ttscommit;

    return lookupTmp;
}
